import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"开放平台","description":"","frontmatter":{},"headers":[],"relativePath":"backend/open-api.md","filePath":"backend/open-api.md","lastUpdated":1794049926000}`),a={name:`backend/open-api.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="开放平台" tabindex="-1">开放平台 <a class="header-anchor" href="#开放平台" aria-label="Permalink to “开放平台”">​</a></h1><p>本页说明 OpenPlatform 包（Tier 2）提供的两种对外接入方式，适用于后端开发者与第三方对接方。</p><table tabindex="0"><thead><tr><th>方式</th><th>适合</th><th>凭据</th></tr></thead><tbody><tr><td>签名开放接口</td><td>服务端到服务端，调用 <code>open.*</code> 操作</td><td>个人中心申请的 AppKey / 密钥，HMAC 签名，可加密请求与响应</td></tr><tr><td>OAuth 2.0 / OIDC 服务端</td><td>第三方应用以用户身份登录、取用户信息</td><td>OAuth 应用的客户端 ID / 密钥，授权码 + PKCE</td></tr></tbody></table><p>本页的「开放接口」与接口文档的 <code>/openapi.json</code>（OpenAPI 规范文档）不是一回事。</p><h2 id="签名开放接口" tabindex="-1">签名开放接口 <a class="header-anchor" href="#签名开放接口" aria-label="Permalink to “签名开放接口”">​</a></h2><h3 id="凭证" tabindex="-1">凭证 <a class="header-anchor" href="#凭证" aria-label="Permalink to “凭证”">​</a></h3><p>开放接口凭证由 Identity 的个人中心自助管理（<code>SysUserApiCredential</code>，密钥加密存储），只要求登录：</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>my-api-credentials.list</code> / <code>create</code> / <code>update</code> / <code>delete</code></td><td>申请与维护凭证</td></tr><tr><td><code>my-api-credentials.rotate-secret</code></td><td>轮换密钥</td></tr><tr><td><code>my-api-credentials.settings</code> / <code>update-settings</code></td><td>签名算法（<code>HmacSHA256</code> / <code>HmacSHA512</code>，缺省 <code>HmacSHA256</code>）与 IP 白名单，作用于本人全部凭证</td></tr></tbody></table><p>凭证停用、或归属人账号不正常时验签一律失败；验签通过即记下凭证的最近使用时间。</p><h3 id="验签中间件" tabindex="-1">验签中间件 <a class="header-anchor" href="#验签中间件" aria-label="Permalink to “验签中间件”">​</a></h3><p><code>RequestSigningMiddleware</code> 在 Authenticate 阶段、只对 <code>open.*</code> 操作生效，依次校验：请求头 → 时间窗（<code>BasicApp:OpenPlatform:TimestampToleranceSeconds</code>，缺省 300 秒，随机串保留它的两倍）→ 凭证 → IP 白名单 → 算法 → 请求体（超限 <code>MaxRequestBodyBytes</code>、解密）→ 内容签名 → 请求签名，最后才占用随机串防重放（伪造的请求不能把正常请求的随机串占掉）。签名用恒定时间比较；失败按类别给 400 / 403 / 409。</p><ul><li>签名恒开，没有「允许不签名」的开关；</li><li>算法以凭证的设置为准，请求头只能与之一致；</li><li>明文请求不必带 <code>X-Encrypt-Algorithm: NONE</code>；</li><li>要求加密响应或请求本身加密时，成功的 JSON 响应换成信封 <code>{alg, data, iv, contentSign}</code>。</li></ul><p>请求头、规范串与加密方式见<a href="./../api-guide">接口对接指南</a>。宿主在 <code>UseXiHan()</code> 之前经 <code>UseOpenApiRequestBuffer</code> 留下请求体原文，验签用原文、加密的先解密再重新绑定载荷。</p><h3 id="开放操作" tabindex="-1">开放操作 <a class="header-anchor" href="#开放操作" aria-label="Permalink to “开放操作”">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>open.ping</code></td><td>验签自检：返回 AppKey、归属人与服务端时间</td></tr><tr><td><code>open.echo</code></td><td>回显（解密后的）请求，核对请求体、内容签名与加密</td></tr></tbody></table><p>验签中间件只对 <code>open.*</code> 操作生效，需要开放给第三方的能力以 <code>open.*</code> 操作的形式新增。</p><h3 id="开放接口日志" tabindex="-1">开放接口日志 <a class="header-anchor" href="#开放接口日志" aria-label="Permalink to “开放接口日志”">​</a></h3><p>每次 <code>open.*</code> 调用无论成败都登记一条开放接口日志（凭证、结果、耗时、请求响应摘要），由 Auditing 落库，<code>open-api-logs.*</code> 查询（<code>auditing.open-api-logs.read</code>），日志落在凭证归属人的注册地一侧。</p><h2 id="oauth-2-0-oidc-服务端" tabindex="-1">OAuth 2.0 / OIDC 服务端 <a class="header-anchor" href="#oauth-2-0-oidc-服务端" aria-label="Permalink to “OAuth 2.0 / OIDC 服务端”">​</a></h2><h3 id="端点" tabindex="-1">端点 <a class="header-anchor" href="#端点" aria-label="Permalink to “端点”">​</a></h3><p>前缀 <code>/api/oauth2</code>，宿主映射的普通端点，绕过内核管道，回原始 OAuth JSON（不是 Problem Details）：</p><table tabindex="0"><thead><tr><th>端点</th><th>说明</th></tr></thead><tbody><tr><td><code>GET /api/oauth2/authorize</code></td><td>把查询串原样带去前端同意页（<code>BasicApp:OpenPlatform:ConsentPageUrl</code>，缺省 <code>/#/oauth/authorize</code>）</td></tr><tr><td><code>POST /api/oauth2/token</code></td><td>表单：<code>authorization_code</code> + PKCE、<code>refresh_token</code>；其他授权类型一律拒绝</td></tr><tr><td><code>POST /api/oauth2/revoke</code></td><td>RFC 7009</td></tr><tr><td><code>GET</code> / <code>POST /api/oauth2/userinfo</code></td><td>用户信息</td></tr><tr><td><code>GET /api/oauth2/.well-known/openid-configuration</code></td><td>OIDC 发现文档</td></tr><tr><td><code>GET /api/oauth2/jwks</code></td><td>签名公钥（<code>SysOAuthSigningKey</code>）</td></tr></tbody></table><p>签发者取 <code>BasicApp:OpenPlatform:Issuer</code>，不配即请求来源加 <code>/api/oauth2</code>；反向代理后必须显式配置。ID 令牌有效期 <code>IdTokenLifetimeSeconds</code>（缺省 600 秒）。</p><h3 id="同意" tabindex="-1">同意 <a class="header-anchor" href="#同意" aria-label="Permalink to “同意”">​</a></h3><p>前端同意页（<code>packages/views/_core/oauth/authorize.vue</code>）用当前登录的用户调用，全部只要求登录：</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>oauth-consents.resolve</code></td><td>解析授权请求，展示应用与请求的范围</td></tr><tr><td><code>oauth-consents.approve</code> / <code>deny</code></td><td>同意或拒绝，同意即签发授权码并重定向</td></tr><tr><td><code>oauth-consents.list</code> / <code>revoke</code></td><td>个人中心「已授权的应用」</td></tr></tbody></table><h3 id="应用管理" tabindex="-1">应用管理 <a class="header-anchor" href="#应用管理" aria-label="Permalink to “应用管理”">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>oauth-apps.list</code> / <code>get</code></td><td><code>openplatform.oauth-apps.read</code></td><td>平台管理全部应用（含用户自助注册的），客户端密钥不回显</td></tr><tr><td><code>oauth-apps.create</code> / <code>update</code> / <code>delete</code></td><td><code>openplatform.oauth-apps.create</code> / <code>update</code> / <code>delete</code></td><td>类型 <code>Web</code> / <code>Mobile</code> / <code>Desktop</code> / <code>Service</code>，客户端 <code>Confidential</code> / <code>Public</code>，回调地址、范围；删除后发给它的令牌即失效</td></tr><tr><td><code>oauth-apps.reset-secret</code></td><td><code>openplatform.oauth-apps.update</code></td><td>重置客户端密钥</td></tr><tr><td><code>my-oauth-apps.list</code> / <code>get</code> / <code>create</code> / <code>update</code> / <code>reset-secret</code> / <code>delete</code></td><td>登录即可</td><td>个人中心「我的应用」：用户自助注册的应用</td></tr></tbody></table><p>权限码只在平台一侧。作业 <code>openplatform.oauth-cleanup</code> 每天 03:30（UTC）物理删除过期一天的授权码与过期七天的令牌。</p><h2 id="第三方登录" tabindex="-1">第三方登录 <a class="header-anchor" href="#第三方登录" aria-label="Permalink to “第三方登录”">​</a></h2><p>用 GitHub、企业微信这类外部身份登录 BasicApp，是 Identity 的能力，见<a href="./authentication">统一认证</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./../api-guide">接口对接指南</a> · <a href="./authentication">统一认证</a> · <a href="./logging">日志审计</a></li></ul>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};